Script.source:
// Doubles what the sensor publishes at /house/room1/temp onto /house/room1/echo;
// a temperature rising past 25 fires Bell, once until it falls below again;
// and counts what arrives under /house/storm/, said once a second.
let above = false;
let heard = 0;
godot.hear('/house/room1/temp', (t) => {
    godot.send('/house/room1/echo', t * 2);
    if (! above && t > 25) {
        above = true;
        godot.fire('B3NK0001');
    } else if (above && t < 25) {
        above = false;
    }
});
godot.hearAll((address) => {
    if (address.indexOf('/house/storm/') === 0) heard += 1;
});
godot.every(1, () => godot.send('/house/stats/heard', heard));
